{$ param image_url label="Image URL" default="https://picsum.photos/800/400" description="Image URL." type="fileurl" $}
{$ param image_alt label="Image Alt" default="" description="Accessibility description of the image." $}
{$ param title label="Title" default="Headline" description="Main heading for the block." $}
{$ param subtitle label="Subtitle" default="" description="Optional secondary heading." $}
{$ param variant label="Variant" default="borderless" description="borderless, light, or dark." $}
{$ param flip label="Flip" default="" description="Any value reverses image and text order." $}
{$ param cta_label label="CTA Label" default="" description="Optional button label." $}
{$ param cta_href label="CTA URL" default="#" description="Button destination URL." $}

<div class="ss-mo ss-mo-{$= variant $} mb-8{$ if flip $} md:flex-row-reverse{$ /if $}">
  <div class="ss-mo-img">
    <img src="{$= image_url $}" alt="{$= image_alt $}" />
  </div>
  <div class="ss-mo-content">
    <h3>{$= title $}</h3>
    {$ if subtitle $}<h4>{$= subtitle $}</h4>{$ /if $}
    {$ slot body $}
      <p>Body copy for the media object.</p>
    {$ /slot $}
    {$ if cta_label $}<a href="{$= cta_href $}" class="btn btn-primary">{$= cta_label $}</a>{$ /if $}
  </div>
</div>
